'use client'
import { useState, useEffect, useRef } from 'react'

const LOGO = 'data:image/png;base64,'

const fmt = (n) => `$${(n || 0).toLocaleString('es-MX', { minimumFractionDigits: 2 })}`

const fmtFecha = (f) => {
  if (!f) return ''
  const meses = ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC']
  const d = new Date(f + 'T12:00:00')
  return `${d.getDate()} ${meses[d.getMonth()]} ${d.getFullYear()}`
}

const fmtFechaCorta = (f) => {
  if (!f) return ''
  const d = new Date(f)
  return d.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' })
}

async function dibujarEstadoCuenta({ cliente, grupos }) {
  const S   = 2
  const W   = 600 * S
  const PAD = 60 * S

  const hdrH   = 120 * S
  const stripe = 72  * S   // expandido para nombre + artículos
  const gap    = 8   * S
  const entLblH = 40 * S
  const tbHdrH  = 34 * S
  const rowH     = 28 * S
  const dateRowH = 12 * S   // línea extra para fecha_compra
  const subH     = 46 * S
  const pgHdrH  = 38 * S   // línea resumen de anticipos
  const liqH    = 52 * S   // strip de liquidación (2 líneas)
  const netoH   = 42 * S   // línea neto por entrega
  const sepH    = 6  * S   // separador antes del total
  const totalH  = 90 * S
  const footH   = 50 * S

  // Total de artículos del estado de cuenta completo
  const totalArticulos = grupos.reduce(
    (s, g) => s + g.pedidos.reduce((ss, p) => ss + (p.cantidad || 1), 0), 0
  )

  // Calcular alto dinámico
  let height = hdrH + stripe + gap
  for (const g of grupos) {
    height += entLblH + tbHdrH + g.pedidos.reduce((s, p) => s + rowH + (p.fecha_compra ? dateRowH : 0), 0) + subH
    const _ant = g.pagos.filter(p => !p.tipo?.toLowerCase().includes('liquidaci'))
    const _liq = g.pagos.filter(p =>  p.tipo?.toLowerCase().includes('liquidaci'))
    if (_ant.length > 0) height += pgHdrH + _ant.length * (20 * S)
    if (_liq.length > 0) height += liqH
    height += netoH + gap
  }
  height += sepH + totalH + footH

  const canvas = document.createElement('canvas')
  canvas.width  = W
  canvas.height = height
  const ctx = canvas.getContext('2d')
  ctx.textBaseline = 'middle'
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, W, height)

  let y = 0

  // ── HEADER ──────────────────────────────────────────────────────
  ctx.fillStyle = '#111827'
  ctx.fillRect(0, y, W, hdrH)

  const logoImg = new Image()
  logoImg.src = LOGO
  await new Promise(r => { logoImg.onload = r; logoImg.onerror = r })
  const lh = 70 * S
  const lw = logoImg.naturalWidth > 0 ? lh * logoImg.naturalWidth / logoImg.naturalHeight : lh
  ctx.drawImage(logoImg, PAD, y + (hdrH - lh) / 2, lw, lh)

  const textX = PAD + lw + 20 * S
  ctx.textAlign = 'left'
  ctx.fillStyle = '#ffffff'
  ctx.font = `bold ${20 * S}px -apple-system,system-ui,sans-serif`
  ctx.fillText('Denog USA Compras', textX, y + hdrH / 2 - 14 * S)
  ctx.fillStyle = '#9ca3af'
  ctx.font = `${13 * S}px -apple-system,system-ui,sans-serif`
  ctx.fillText('Estado de cuenta', textX, y + hdrH / 2 + 12 * S)

  ctx.fillStyle = '#f59e0b'
  ctx.fillRect(0, y + hdrH - 3 * S, W, 3 * S)
  y += hdrH

  // ── CLIENT STRIPE (nombre + artículos / fecha) ───────────────────
  ctx.fillStyle = '#1e3a5f'
  ctx.fillRect(0, y, W, stripe)

  // Nombre del cliente
  ctx.fillStyle = '#ffffff'
  ctx.font = `bold ${16 * S}px -apple-system,system-ui,sans-serif`
  ctx.textAlign = 'left'
  ctx.fillText((cliente.nombre || '').toUpperCase(), PAD, y + stripe / 2 - 11 * S)

  // X artículos debajo del nombre
  ctx.fillStyle = '#93c5fd'
  ctx.font = `${11 * S}px -apple-system,system-ui,sans-serif`
  ctx.fillText(totalArticulos + ' artículo' + (totalArticulos !== 1 ? 's' : ''), PAD, y + stripe / 2 + 11 * S)

  // Fecha a la derecha (centrada verticalmente)
  if (grupos.length === 1 && grupos[0].entrega) {
    ctx.fillStyle = '#93c5fd'
    ctx.font = `${12 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'right'
    ctx.fillText(fmtFecha(grupos[0].entrega.fecha_entrega), W - PAD, y + stripe / 2)
    ctx.textAlign = 'left'
  }
  y += stripe + gap

  // ── GRUPOS POR ENTREGA ──────────────────────────────────────────
  const netos = []

  for (const g of grupos) {
    const totalEntregados = g.totalEntregadosOriginal ?? g.pedidos.filter(p => p.estado === 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
    const totalPendientes = g.pedidos.filter(p => p.estado !== 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
    const pagadoGrupo = g.pagos.reduce((s, p) => s + (p.monto || 0), 0)
    const sobrante = Math.max(0, pagadoGrupo - totalEntregados)
    const neto = Math.max(0, totalPendientes - sobrante)
    netos.push(neto)

    // Label entrega
    ctx.fillStyle = '#f8fafc'
    ctx.fillRect(0, y, W, entLblH)
    ctx.fillStyle = '#f59e0b'
    ctx.fillRect(0, y, 4 * S, entLblH)
    ctx.fillStyle = '#374151'
    ctx.font = `bold ${12 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'left'
    ctx.fillText(
      g.entrega ? '📦 ENTREGA: ' + fmtFecha(g.entrega.fecha_entrega) : '📦 PEDIDOS PENDIENTES',
      PAD + 6 * S, y + entLblH / 2
    )
    y += entLblH

    // Header tabla productos
    ctx.fillStyle = '#374151'
    ctx.fillRect(0, y, W, tbHdrH)
    ctx.fillStyle = '#ffffff'
    ctx.font = `bold ${11 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'left'
    ctx.fillText('PRODUCTO', PAD, y + tbHdrH / 2)
    ctx.textAlign = 'center'
    ctx.fillText('CANT', W - 170 * S, y + tbHdrH / 2)
    ctx.textAlign = 'right'
    ctx.fillText('PRECIO', W - PAD, y + tbHdrH / 2)
    ctx.textAlign = 'left'
    y += tbHdrH

    // Filas de productos
    g.pedidos.forEach((p, i) => {
      const thisRowH = rowH + (p.fecha_compra ? dateRowH : 0)
      ctx.fillStyle = i % 2 === 0 ? '#ffffff' : '#f9fafb'
      ctx.fillRect(0, y, W, thisRowH)
      ctx.fillStyle = '#f3f4f6'
      ctx.fillRect(0, y + thisRowH - 1, W, 1)

      const textY = p.fecha_compra ? y + rowH * 0.35 : y + rowH / 2

      ctx.font = `${13 * S}px -apple-system,system-ui,sans-serif`
      const maxW = W - PAD * 2 - 220 * S
      let desc = p.descripcion || ''
      while (desc.length > 5 && ctx.measureText(desc).width > maxW) desc = desc.slice(0, -1)
      if (desc !== (p.descripcion || '')) desc += '…'
      ctx.fillStyle = '#9ca3af'
      ctx.textAlign = 'left'
      ctx.fillText('• ', PAD, textY)
      const bulletW = ctx.measureText('• ').width
      ctx.fillStyle = '#111827'
      ctx.fillText(desc, PAD + bulletW, textY)

      ctx.fillStyle = '#6b7280'
      ctx.textAlign = 'center'
      ctx.fillText(String(p.cantidad || 1), W - 170 * S, textY)

      ctx.fillStyle = '#111827'
      ctx.font = `bold ${13 * S}px -apple-system,system-ui,sans-serif`
      ctx.textAlign = 'right'
      ctx.fillText(fmt(p.precio_venta), W - PAD, textY)
      ctx.textAlign = 'left'

      if (p.fecha_compra) {
        ctx.fillStyle = '#9ca3af'
        ctx.font = `${10 * S}px -apple-system,system-ui,sans-serif`
        ctx.fillText('Comprado: ' + fmtFecha(p.fecha_compra), PAD, y + rowH + dateRowH * 0.5)
      }

      y += thisRowH
    })

    // Subtotal entrega (amarillo)
    ctx.fillStyle = '#fef9c3'
    ctx.fillRect(0, y, W, subH)
    ctx.fillStyle = '#92400e'
    ctx.font = `bold ${12 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'left'
    ctx.fillText('Subtotal:', PAD, y + subH / 2)
    ctx.font = `bold ${15 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'right'
    ctx.fillText(fmt(totalPendientes), W - PAD, y + subH / 2)
    ctx.textAlign = 'left'
    y += subH

    // Strips de pagos: anticipos (verde) y liquidación (azul) por separado
    // Ocultar si es entrega vieja con pagos ya aplicados (totalEntregadosOriginal indica que fue filtrada)
    const ocultarPagos = g.totalEntregadosOriginal !== undefined
    const pagsAnt = g.pagos.filter(p => !p.tipo?.toLowerCase().includes('liquidaci'))
    const pagsLiq = g.pagos.filter(p =>  p.tipo?.toLowerCase().includes('liquidaci'))

    if (!ocultarPagos && pagsAnt.length > 0) {
      const totalAnt = pagsAnt.reduce((s, p) => s + (p.monto || 0), 0)
      const antDetH = pagsAnt.length * (20 * S)
      const antTotalH = pgHdrH + antDetH
      const emojiMetC = (m) => m === 'Efectivo' ? '💵' : m === 'Transferencia' ? '📱' : m === 'Terminal' ? '💳' : m

      ctx.fillStyle = '#dcfce7'
      ctx.fillRect(0, y, W, antTotalH)
      ctx.fillStyle = '#166534'
      ctx.font = `bold ${12 * S}px -apple-system,system-ui,sans-serif`
      ctx.textAlign = 'left'
      ctx.fillText('✓ Anticipos aplicados:', PAD, y + pgHdrH / 2)
      ctx.textAlign = 'right'
      ctx.fillText('−' + fmt(totalAnt), W - PAD, y + pgHdrH / 2)
      ctx.textAlign = 'left'

      pagsAnt.forEach((ant, idx) => {
        const lineY = y + pgHdrH + idx * (20 * S) + 10 * S
        const fechaAntTxt = ant.creado_en ? fmtFecha(ant.creado_en.split('T')[0]) : ''
        ctx.fillStyle = '#15803d'
        ctx.font = `${10 * S}px -apple-system,system-ui,sans-serif`
        ctx.fillText(`  ${emojiMetC(ant.metodo)} ${ant.metodo || ''}: ${fmt(ant.monto)}${fechaAntTxt ? ' · ' + fechaAntTxt : ''}`, PAD, lineY)
      })

      y += antTotalH
    }

    if (!ocultarPagos && pagsLiq.length > 0) {
      const totalLiq = pagsLiq.reduce((s, p) => s + (p.monto || 0), 0)
      const fechaLiq = pagsLiq[0]?.creado_en
      const emojiMet = (m) => m === 'Efectivo' ? '💵' : m === 'Transferencia' ? '📱' : m === 'Terminal' ? '💳' : m
      const porMet = pagsLiq.reduce((acc, p) => {
        if (!p.metodo) return acc
        acc[p.metodo] = (acc[p.metodo] || 0) + p.monto
        return acc
      }, {})
      const metTxt = Object.entries(porMet).map(([m, monto]) => `${emojiMet(m)} ${m}: ${fmt(monto)}`).join('  ')

      ctx.fillStyle = '#dbeafe'
      ctx.fillRect(0, y, W, liqH)
      ctx.fillStyle = '#1d4ed8'
      ctx.fillRect(0, y, 4 * S, liqH)

      ctx.fillStyle = '#1e3a8a'
      ctx.font = `bold ${12 * S}px -apple-system,system-ui,sans-serif`
      ctx.textAlign = 'left'
      ctx.fillText('✓ Liquidado' + (fechaLiq ? ' · ' + fmtFecha(fechaLiq.split('T')[0]) : ''), PAD + 6 * S, y + liqH * 0.32)
      ctx.textAlign = 'right'
      ctx.fillText(fmt(totalLiq), W - PAD, y + liqH * 0.32)

      ctx.fillStyle = '#3b82f6'
      ctx.font = `${10 * S}px -apple-system,system-ui,sans-serif`
      ctx.textAlign = 'left'
      ctx.fillText(metTxt, PAD + 6 * S, y + liqH * 0.72)
      ctx.textAlign = 'left'
      y += liqH
    }

    // Neto de esta entrega (azul)
    ctx.fillStyle = '#e0f2fe'
    ctx.fillRect(0, y, W, netoH)
    ctx.fillStyle = '#0ea5e9'
    ctx.fillRect(0, y, 4 * S, netoH)
    ctx.fillStyle = '#0c4a6e'
    ctx.font = `bold ${12 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'left'
    ctx.fillText('Neto entrega:', PAD + 6 * S, y + netoH / 2)
    ctx.font = `bold ${15 * S}px -apple-system,system-ui,sans-serif`
    ctx.textAlign = 'right'
    ctx.fillText(fmt(neto), W - PAD, y + netoH / 2)
    ctx.textAlign = 'left'
    y += netoH + gap
  }

  // ── SEPARADOR ────────────────────────────────────────────────────
  ctx.fillStyle = '#374151'
  ctx.fillRect(0, y, W, sepH)
  y += sepH

  // ── TOTAL A PAGAR (suma de todos los netos) ──────────────────────
  const totalFinal = netos.reduce((s, n) => s + n, 0)
  ctx.fillStyle = '#111827'
  ctx.fillRect(0, y, W, totalH)
  ctx.fillStyle = '#9ca3af'
  ctx.font = `${14 * S}px -apple-system,system-ui,sans-serif`
  ctx.textAlign = 'left'
  ctx.fillText('TOTAL A PAGAR', PAD, y + totalH / 2 - 18 * S)
  ctx.fillStyle = '#f59e0b'
  ctx.font = `bold ${32 * S}px -apple-system,system-ui,sans-serif`
  ctx.textAlign = 'right'
  ctx.fillText(fmt(totalFinal), W - PAD, y + totalH / 2 + 10 * S)
  ctx.textAlign = 'left'
  y += totalH

  // ── FOOTER ───────────────────────────────────────────────────────
  ctx.fillStyle = '#1f2937'
  ctx.fillRect(0, y, W, footH)
  ctx.fillStyle = '#6b7280'
  ctx.font = `${12 * S}px -apple-system,system-ui,sans-serif`
  ctx.textAlign = 'center'
  ctx.fillText('¡Gracias por tu Happy Shopping! 📦  ·  denog.mx', W / 2, y + footH / 2)

  return canvas
}


export default function EstadosCuenta() {
  const [modo, setModo] = useState('entrega')
  const [entregas, setEntregas] = useState([])
  const [clientes, setClientes] = useState([])
  const [entregaId, setEntregaId] = useState('')
  const [clienteId, setClienteId] = useState('')
  const [busqueda, setBusqueda] = useState('')
  const [datos, setDatos] = useState([])
  const [indice, setIndice] = useState(0)
  const [cargando, setCargando] = useState(false)
  const [copiado, setCopiado] = useState(false)
  const [errorClip, setErrorClip] = useState(false)
  const [imagenURL, setImagenURL] = useState(null)
  const canvasRef = useRef(null)

  // Edición de pedidos
  const [todosClientes, setTodosClientes] = useState([])
  const [vendedoresOpts, setVendedoresOpts] = useState([])
  const [editandoPedido, setEditandoPedido] = useState(null)
  const [editFormPedido, setEditFormPedido] = useState({})
  const [guardandoPedido, setGuardandoPedido] = useState(false)
  const [pedidoMsg, setPedidoMsg] = useState('')
  const [ecTaxTipo, setEcTaxTipo] = useState('arizona')
  const [ecTaxDenogPct, setEcTaxDenogPct] = useState('')

  useEffect(() => {
    Promise.all([
      fetch('/api/entregas').then(r => r.json()),
      fetch('/api/clientes/listar').then(r => r.json())
    ]).then(([e, c]) => {
      if (e.ok) setEntregas(e.entregas)
      if (c.ok) {
        setClientes(c.clientes.filter(cl => cl.rol !== 'admin'))
        setTodosClientes(c.clientes)
        setVendedoresOpts(c.clientes.filter(cl => cl.rol === 'admin' || cl.rol === 'vendedor'))
      }
    })
  }, [])

  const abrirEditarPedido = (p) => {
    const imp = parseFloat(p.impuesto_pct) || 0
    const taxTipo = Math.abs(imp - 8.6) < 0.01 ? 'arizona' : Math.abs(imp - 7.75) < 0.01 ? 'california' : 'denog'
    setEcTaxTipo(taxTipo)
    setEcTaxDenogPct(taxTipo === 'denog' && imp > 0 ? String(imp) : '')
    setEditandoPedido(p.id)
    setEditFormPedido({
      cliente_id: p.cliente_id || '',
      entrega_id: p.entrega_id || '',
      descripcion: p.descripcion || '',
      lugar_compra: p.lugar_compra || '',
      cantidad: p.cantidad ?? 1,
      fecha_compra: p.fecha_compra || '',
      precio_usd: p.precio_usd ?? '',
      tipo_cambio: p.tipo_cambio ?? '',
      impuesto_pct: p.impuesto_pct ?? '',
      costo_mxn: p.costo_mxn ?? '',
      precio_venta: p.precio_venta ?? '',
      utilidad: p.utilidad ?? '',
      notas: p.notas || '',
      estado: p.estado || '',
      vendedor_id: p.vendedor_id || '',
    })
    setPedidoMsg('')
  }

  const guardarPedidoEdit = async () => {
    setGuardandoPedido(true)
    const res = await fetch('/api/pedidos/actualizar-pedido', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: editandoPedido, ...editFormPedido })
    })
    const data = await res.json()
    setGuardandoPedido(false)
    if (data.ok) {
      setEditandoPedido(null)
      if (modo === 'entrega') cargarPorEntrega()
      else cargarPorCliente()
    } else {
      setPedidoMsg(data.mensaje || 'Error al guardar')
    }
  }

  const eliminarPedido = async (pedidoId) => {
    if (!confirm('¿Eliminar este artículo? Esta acción no se puede deshacer.')) return
    const res = await fetch('/api/pedidos/actualizar-pedido', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: pedidoId })
    })
    const data = await res.json()
    if (data.ok) {
      if (modo === 'entrega') cargarPorEntrega()
      else cargarPorCliente()
    }
  }

  const cargarPorEntrega = async () => {
    if (!entregaId) return
    setCargando(true)
    setDatos([])

    // Paso 1: identificar qué clientes tienen pedidos en la entrega seleccionada
    // Paso 2: traer TODOS los pedidos y pagos sin filtro de entrega
    const [pedsEntregaRes, todosPedsRes, todosPagsRes] = await Promise.all([
      fetch(`/api/reportes/pedidos?entrega_id=${entregaId}`).then(r => r.json()),
      fetch('/api/reportes/pedidos').then(r => r.json()),
      fetch('/api/reportes/pagos').then(r => r.json())
    ])

    // IDs de clientes que aparecen en la entrega seleccionada
    const clientesEnEntrega = new Set(
      (pedsEntregaRes.pedidos || []).map(p => String(p.cliente_id))
    )
    if (clientesEnEntrega.size === 0) { setCargando(false); return }

    const todosPedidos = (todosPedsRes.pedidos || []).filter(p =>
      clientesEnEntrega.has(String(p.cliente_id))
    )

    // Todos los pagos de esos clientes (cualquier entrega)
    const todosPagos = (todosPagsRes.pagos || []).filter(p =>
      clientesEnEntrega.has(String(p.cliente_id))
    )

    // Agrupar: cliente → entrega → { pedidos, pagos }
    const porCliente = {}
    todosPedidos.forEach(p => {
      const cid = String(p.cliente_id)
      if (!porCliente[cid]) porCliente[cid] = { nombre: p.clientes?.nombre || '', porEntrega: {} }
      const eid = String(p.entrega_id || 'sin')
      if (!porCliente[cid].porEntrega[eid]) porCliente[cid].porEntrega[eid] = { pedidos: [], pagos: [] }
      porCliente[cid].porEntrega[eid].pedidos.push(p)
    })
    todosPagos.forEach(p => {
      const cid = String(p.cliente_id)
      if (!porCliente[cid]) return
      const eid = String(p.entrega_id || 'sin')
      if (porCliente[cid].porEntrega[eid]) {
        porCliente[cid].porEntrega[eid].pagos.push(p)
      } else {
        console.warn('[estados-cuenta cargarPorEntrega] pago SIN grupo — tipo:', p.tipo, 'entrega_id:', p.entrega_id, 'eids del cliente:', Object.keys(porCliente[cid]?.porEntrega || {}))
      }
    })

    const lista = Object.entries(porCliente).map(([id, d]) => {
      const cl = clientes.find(c => String(c.id) === id)
      let grupos = Object.entries(d.porEntrega).map(([eid, data]) => ({
        entrega: entregas.find(e => String(e.id) === eid) || null,
        pedidos: data.pedidos,
        pagos: data.pagos
      })).sort((a, b) => {
        if (!a.entrega) return 1
        if (!b.entrega) return -1
        return new Date(a.entrega.fecha_entrega) - new Date(b.entrega.fecha_entrega)
      })

      // En entregas anteriores a la más reciente, ocultar pedidos ya entregados
      // (el recordatorio solo debe mostrar lo pendiente de recoger).
      // Si la entrega que se está consultando NO es la más reciente del cliente,
      // se muestra todo tal cual (evidencia histórica completa).
      const fechaMasReciente = grupos.reduce((max, g) => {
        if (!g.entrega) return max
        const f = new Date(g.entrega.fecha_entrega)
        return (!max || f > max) ? f : max
      }, null)
      const entregaConsultada = entregas.find(e => String(e.id) === String(entregaId))
      const consultandoLaMasReciente = entregaConsultada && fechaMasReciente &&
        new Date(entregaConsultada.fecha_entrega).getTime() === fechaMasReciente.getTime()

      if (consultandoLaMasReciente) {
        grupos = grupos.map(g => {
          const esLaMasReciente = g.entrega && fechaMasReciente && new Date(g.entrega.fecha_entrega).getTime() === fechaMasReciente.getTime()
          if (esLaMasReciente) return g
          const pedidosPendientes = g.pedidos.filter(p => p.estado !== 'Entregado')
          const totalEntregadosOriginal = g.pedidos.filter(p => p.estado === 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
          // Si ya no quedan pedidos pendientes en este grupo viejo, el grupo completo
          // (incluyendo sus anticipos) deja de mostrarse en el estado de cuenta actual
          if (pedidosPendientes.length === 0) return { ...g, pedidos: [], pagos: [] }
          return { ...g, pedidos: pedidosPendientes, totalEntregadosOriginal }
        }).filter(g => g.pedidos.length > 0 || g.pagos.length > 0)
      }

      return {
        cliente: { id, nombre: d.nombre || cl?.nombre || '', telefono: cl?.telefono || '' },
        grupos
      }
    }).sort((a, b) => a.cliente.nombre.localeCompare(b.cliente.nombre, 'es'))

    setDatos(lista)
    setIndice(0)
    setCargando(false)
  }

  const cargarPorCliente = async () => {
    if (!clienteId) return
    setCargando(true)
    setDatos([])
    const cl = clientes.find(c => String(c.id) === String(clienteId))

    // Filtrar server-side por cliente_id para evitar el límite de 1000 filas de Supabase
    const [pedsRes, pagsRes] = await Promise.all([
      fetch(`/api/reportes/pedidos?cliente_id=${clienteId}`).then(r => r.json()),
      fetch(`/api/reportes/pagos?cliente_id=${clienteId}`).then(r => r.json())
    ])

    const pedidos = pedsRes.pedidos || []
    const pagos = pagsRes.pagos || []

    const porEntrega = {}
    pedidos.forEach(p => {
      const eid = String(p.entrega_id || 'sin')
      if (!porEntrega[eid]) porEntrega[eid] = { pedidos: [], pagos: [] }
      porEntrega[eid].pedidos.push(p)
    })
    const keysEntrega = Object.keys(porEntrega)
    pagos.forEach(p => {
      const eid = String(p.entrega_id || 'sin')
      if (porEntrega[eid]) {
        porEntrega[eid].pagos.push(p)
      } else {
        console.warn('[estados-cuenta] pago SIN grupo coincidente — tipo:', p.tipo, 'entrega_id:', p.entrega_id, 'eids disponibles:', keysEntrega)
      }
    })

    let grupos = Object.entries(porEntrega).map(([eid, d]) => ({
      entrega: entregas.find(e => String(e.id) === eid) || null,
      pedidos: d.pedidos,
      pagos: d.pagos
    })).sort((a, b) => {
      if (!a.entrega) return 1
      if (!b.entrega) return -1
      return new Date(a.entrega.fecha_entrega) - new Date(b.entrega.fecha_entrega)
    })

    // En entregas anteriores a la más reciente, ocultar pedidos ya entregados
    // (el recordatorio solo debe mostrar lo pendiente de recoger).
    // Si se filtró por una entrega vieja específica, se muestra todo (evidencia histórica).
    const fechaMasReciente = grupos.reduce((max, g) => {
      if (!g.entrega) return max
      const f = new Date(g.entrega.fecha_entrega)
      return (!max || f > max) ? f : max
    }, null)
    const entregaConsultada = entregaId ? entregas.find(e => String(e.id) === String(entregaId)) : null
    const consultandoEntregaVieja = entregaConsultada && fechaMasReciente &&
      new Date(entregaConsultada.fecha_entrega).getTime() !== fechaMasReciente.getTime()

    if (!consultandoEntregaVieja) {
      grupos = grupos.map(g => {
        const esLaMasReciente = g.entrega && fechaMasReciente && new Date(g.entrega.fecha_entrega).getTime() === fechaMasReciente.getTime()
        if (esLaMasReciente) return g
        const pedidosPendientes = g.pedidos.filter(p => p.estado !== 'Entregado')
        const totalEntregadosOriginal = g.pedidos.filter(p => p.estado === 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
        // Si ya no quedan pedidos pendientes en este grupo viejo, el grupo completo
        // (incluyendo sus anticipos) deja de mostrarse en el estado de cuenta actual
        if (pedidosPendientes.length === 0) return { ...g, pedidos: [], pagos: [] }
        return { ...g, pedidos: pedidosPendientes, totalEntregadosOriginal }
      }).filter(g => g.pedidos.length > 0 || g.pagos.length > 0)
    }

    if (grupos.length === 0) { setCargando(false); return }

    setDatos([{ cliente: { id: clienteId, nombre: cl?.nombre || '', telefono: cl?.telefono || '' }, grupos }])
    setIndice(0)
    setCargando(false)
  }

  const copiarAlPortapapeles = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    try {
      // Pasar el blob como Promise a ClipboardItem de forma síncrona dentro del gesto de usuario
      const blobPromise = new Promise(resolve => canvas.toBlob(resolve, 'image/png'))
      navigator.clipboard.write([new ClipboardItem({ 'image/png': blobPromise })])
        .then(() => {
          setCopiado(true)
          setErrorClip(false)
          setTimeout(() => setCopiado(false), 2500)
        })
        .catch(e => {
          console.error('[Copia] Error:', e.name, e.message)
          setErrorClip(true)
          setTimeout(() => setErrorClip(false), 3000)
        })
    } catch (e) {
      console.error('[Copia] Error al crear ClipboardItem:', e.name, e.message)
      setErrorClip(true)
      setTimeout(() => setErrorClip(false), 3000)
    }
  }

  useEffect(() => {
    if (datos.length > 0 && datos[indice]) {
      setImagenURL(null)
      dibujarEstadoCuenta(datos[indice]).then(canvas => {
        canvasRef.current = canvas
        setImagenURL(canvas.toDataURL('image/png'))
      })
    }
  }, [indice, datos])

  const siguiente = () => { if (indice < datos.length - 1) setIndice(i => i + 1) }

  const clienteActual = datos[indice]
  const clientesFiltrados = busqueda.length > 1
    ? clientes.filter(c => c.nombre.toLowerCase().includes(busqueda.toLowerCase()))
    : []

  const inputStyle = { width: '100%', background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: 8, padding: '9px 12px', color: 'white', fontSize: 13, outline: 'none', boxSizing: 'border-box' }
  const labelStyle = { color: 'rgba(255,255,255,0.4)', fontSize: 11, textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }

  return (
    <div style={{ minHeight: '100vh', background: '#030712', padding: '24px 20px' }}>
      <div style={{ maxWidth: 680, margin: '0 auto' }}>

        {/* Header */}
        <div style={{ marginBottom: 24 }}>
          <div style={{ color: 'white', fontSize: 20, fontWeight: 700 }}>📋 Estados de cuenta</div>
          <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 13, marginTop: 4 }}>Genera y comparte por WhatsApp — copia la imagen y pégala en el chat</div>
        </div>

        {/* Mode tabs */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 20 }}>
          {[['entrega', '📅 Por entrega'], ['cliente', '🔍 Buscar cliente']].map(([m, lbl]) => (
            <button key={m} onClick={() => { setModo(m); setDatos([]); setIndice(0) }}
              style={{ padding: '8px 18px', borderRadius: 10, border: `1px solid ${modo === m ? 'rgba(99,102,241,0.5)' : 'rgba(255,255,255,0.1)'}`, background: modo === m ? 'rgba(99,102,241,0.15)' : 'rgba(255,255,255,0.04)', color: modo === m ? '#818cf8' : 'rgba(255,255,255,0.5)', fontSize: 13, fontWeight: modo === m ? 600 : 400, cursor: 'pointer' }}>
              {lbl}
            </button>
          ))}
        </div>

        {/* Filters */}
        <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.07)', borderRadius: 14, padding: '16px 20px', marginBottom: 20 }}>
          {modo === 'entrega' ? (
            <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end' }}>
              <div style={{ flex: 1 }}>
                <label style={labelStyle}>Entrega</label>
                <select value={entregaId} onChange={e => setEntregaId(e.target.value)} style={{ ...inputStyle }}>
                  <option value="">Selecciona una entrega</option>
                  {entregas.map(e => <option key={e.id} value={e.id}>{fmtFecha(e.fecha_entrega)}{e.nota ? ' · ' + e.nota : ''}</option>)}
                </select>
              </div>
              <button onClick={cargarPorEntrega} disabled={!entregaId || cargando}
                style={{ padding: '9px 20px', borderRadius: 8, background: 'rgba(99,102,241,0.2)', border: '1px solid rgba(99,102,241,0.3)', color: '#818cf8', fontSize: 13, fontWeight: 600, cursor: 'pointer', opacity: !entregaId || cargando ? 0.5 : 1, whiteSpace: 'nowrap' }}>
                {cargando ? 'Cargando...' : 'Cargar clientes'}
              </button>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              <div style={{ position: 'relative' }}>
                <label style={labelStyle}>Cliente</label>
                <input value={busqueda} onChange={e => { setBusqueda(e.target.value); setClienteId('') }} placeholder="Escribe el nombre..."
                  style={inputStyle} />
                {clientesFiltrados.length > 0 && !clienteId && (
                  <div style={{ position: 'absolute', left: 0, right: 0, top: '100%', background: '#0f172a', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 8, zIndex: 10, maxHeight: 200, overflowY: 'auto', marginTop: 2 }}>
                    {clientesFiltrados.map(c => (
                      <div key={c.id} onClick={() => { setClienteId(c.id); setBusqueda(c.nombre) }}
                        style={{ padding: '10px 14px', cursor: 'pointer', color: 'white', fontSize: 13, borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                        {c.nombre}
                      </div>
                    ))}
                  </div>
                )}
              </div>
              <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end' }}>
                <div style={{ flex: 1 }}>
                  <label style={labelStyle}>Entrega (opcional)</label>
                  <select value={entregaId} onChange={e => setEntregaId(e.target.value)} style={{ ...inputStyle }}>
                    <option value="">Todas las entregas</option>
                    {entregas.map(e => <option key={e.id} value={e.id}>{fmtFecha(e.fecha_entrega)}</option>)}
                  </select>
                </div>
                <button onClick={cargarPorCliente} disabled={!clienteId || cargando}
                  style={{ padding: '9px 20px', borderRadius: 8, background: 'rgba(99,102,241,0.2)', border: '1px solid rgba(99,102,241,0.3)', color: '#818cf8', fontSize: 13, fontWeight: 600, cursor: 'pointer', opacity: !clienteId || cargando ? 0.5 : 1, whiteSpace: 'nowrap' }}>
                  {cargando ? 'Cargando...' : 'Ver estado'}
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Client view */}
        {datos.length > 0 && clienteActual && (
          <>
            {/* Navegación avanzada */}
            <div className="flex items-center gap-2 flex-wrap justify-center mb-4">
              <button
                onClick={() => setIndice(0)}
                disabled={indice === 0}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >⏮ Primero</button>

              <button
                onClick={() => setIndice(i => Math.max(0, i - 10))}
                disabled={indice === 0}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >-10</button>

              <button
                onClick={() => setIndice(i => Math.max(0, i - 1))}
                disabled={indice === 0}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >◀ Ant</button>

              <div className="flex items-center gap-1">
                <span className="text-gray-400 text-sm">Cliente</span>
                <input
                  type="number"
                  min={1}
                  max={datos.length}
                  value={indice + 1}
                  onChange={e => {
                    const val = parseInt(e.target.value);
                    if (!isNaN(val) && val >= 1 && val <= datos.length) setIndice(val - 1);
                  }}
                  className="w-14 text-center bg-gray-800 border border-gray-600 rounded-lg text-white text-sm py-1"
                />
                <span className="text-gray-400 text-sm">de {datos.length}</span>
              </div>

              <button
                onClick={() => setIndice(i => Math.min(datos.length - 1, i + 1))}
                disabled={indice === datos.length - 1}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >Sig ▶</button>

              <button
                onClick={() => setIndice(i => Math.min(datos.length - 1, i + 10))}
                disabled={indice === datos.length - 1}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >+10</button>

              <button
                onClick={() => setIndice(datos.length - 1)}
                disabled={indice === datos.length - 1}
                className="px-3 py-1 rounded-lg bg-gray-700 text-white text-sm disabled:opacity-30"
              >⏭ Último</button>
            </div>

            {/* Client card */}
            <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 16, padding: '20px 24px', marginBottom: 14 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                <div>
                  <div style={{ color: 'white', fontSize: 18, fontWeight: 700 }}>{clienteActual.cliente.nombre}</div>
                  {clienteActual.cliente.telefono && (
                    <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 12, marginTop: 3 }}>📱 {clienteActual.cliente.telefono}</div>
                  )}
                </div>

              </div>

              {clienteActual.grupos.map((g, gi) => {
                const totalEntregados = g.totalEntregadosOriginal ?? g.pedidos.filter(p => p.estado === 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
                const sub = g.pedidos.filter(p => p.estado !== 'Entregado').reduce((s, p) => s + (p.precio_venta || 0), 0)
                const pagAnt = g.pagos.filter(p => !p.tipo?.toLowerCase().includes('liquidaci')).reduce((s, p) => s + (p.monto || 0), 0)
                const pag = g.pagos.reduce((s, p) => s + (p.monto || 0), 0)
                const sobrante = Math.max(0, pag - totalEntregados)
                const neto = Math.max(0, sub - sobrante)
                return (
                  <div key={gi} style={{ marginBottom: gi < clienteActual.grupos.length - 1 ? 16 : 0 }}>
                    {clienteActual.grupos.length > 1 && g.entrega && (
                      <div style={{ color: '#818cf8', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 8 }}>
                        Entrega {fmtFecha(g.entrega.fecha_entrega)}
                      </div>
                    )}
                    <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 10, overflow: 'hidden', marginBottom: 8 }}>
                      {[...g.pedidos].sort(p => p.estado === 'Entregado' ? 1 : -1).map((p, pi, arr) => (
                        <div key={pi} style={{ opacity: p.estado === 'Entregado' ? 0.6 : 1 }}>
                          {editandoPedido !== p.id ? (
                            <div style={{ padding: '6px 14px', borderBottom: pi < arr.length - 1 ? '1px solid #f0f0f0' : 'none' }}>
                              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <div style={{ flex: 1, marginRight: 12 }}>
                                  <span style={{ color: 'rgba(255,255,255,0.65)', fontSize: 12 }}>{p.descripcion}</span>
                                  {p.apartado_fragil && (
                                    <span style={{ background: '#facc15', color: '#000', fontSize: '10px', fontWeight: 'bold', padding: '1px 6px', borderRadius: '4px', marginLeft: '6px' }}>
                                      ⚠️ APARTADOS / FRÁGIL
                                    </span>
                                  )}
                                  {p.fecha_compra && (
                                    <div style={{ color: 'rgba(255,255,255,0.3)', fontSize: 10, marginTop: 1 }}>
                                      Comprado: {fmtFecha(p.fecha_compra)}
                                    </div>
                                  )}
                                </div>
                                <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexShrink: 0 }}>
                                  <span style={{ color: 'white', fontSize: 12, fontWeight: 600 }}>
                                    {(p.cantidad || 1) > 1 ? `x${p.cantidad} = ${fmt(p.precio_venta)}` : fmt(p.precio_venta)}
                                  </span>
                                  {p.estado !== 'Entregado' && (
                                    <>
                                      <button onClick={() => abrirEditarPedido(p)}
                                        style={{ background: 'rgba(99,102,241,0.1)', border: '1px solid rgba(99,102,241,0.2)', borderRadius: 6, padding: '3px 9px', color: '#818cf8', fontSize: 10, fontWeight: 600, cursor: 'pointer' }}>
                                        ✏️
                                      </button>
                                      <button
                                        onClick={async () => {
                                          const nuevoValor = !p.apartado_fragil;
                                          await fetch('/api/pedidos/actualizar-pedido', {
                                            method: 'PUT',
                                            headers: { 'Content-Type': 'application/json' },
                                            body: JSON.stringify({ ...p, apartado_fragil: nuevoValor })
                                          });
                                          setDatos(prev => prev.map(cliente => ({
                                            ...cliente,
                                            grupos: cliente.grupos.map(g => ({
                                              ...g,
                                              pedidos: g.pedidos.map(ped =>
                                                ped.id === p.id ? { ...ped, apartado_fragil: nuevoValor } : ped
                                              )
                                            }))
                                          })));
                                        }}
                                        title={p.apartado_fragil ? 'Quitar APARTADOS/FRÁGIL' : 'Marcar APARTADOS/FRÁGIL'}
                                        style={{ background: p.apartado_fragil ? '#facc15' : 'rgba(250,204,21,0.15)', color: p.apartado_fragil ? '#000' : '#facc15', border: '1px solid #facc15', borderRadius: '6px', padding: '2px 7px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' }}>
                                        ⚠️
                                      </button>
                                      <button onClick={() => eliminarPedido(p.id)}
                                        style={{ background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 6, padding: '3px 9px', color: '#f87171', fontSize: 10, fontWeight: 600, cursor: 'pointer' }}>
                                        🗑️
                                      </button>
                                    </>
                                  )}
                                </div>
                              </div>
                              {p.estado === 'Entregado' && (
                                <div style={{ marginTop: 4 }}>
                                  <span style={{ background: '#10b981', color: 'white', fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 4, letterSpacing: 0.5 }}>✓ ENTREGADO</span>
                                </div>
                              )}
                            </div>
                          ) : (
                            <div style={{ background: 'rgba(99,102,241,0.07)', border: '1px solid rgba(99,102,241,0.2)', borderRadius: 10, padding: 14, margin: 6 }}>
                              <div style={{ color: 'rgba(255,255,255,0.5)', fontSize: 10, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 10 }}>Editar pedido</div>
                              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 8 }}>
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Cliente</label>
                                  <select value={editFormPedido.cliente_id} onChange={ev => setEditFormPedido({ ...editFormPedido, cliente_id: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }}>
                                    <option value="">— seleccionar —</option>
                                    {todosClientes.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}
                                  </select>
                                </div>
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Entrega</label>
                                  <select value={editFormPedido.entrega_id} onChange={ev => setEditFormPedido({ ...editFormPedido, entrega_id: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }}>
                                    <option value="">— seleccionar —</option>
                                    {entregas.map(en => <option key={en.id} value={en.id}>{en.fecha_entrega}{en.nota ? ` · ${en.nota}` : ''}</option>)}
                                  </select>
                                </div>
                                <div style={{ gridColumn: '1 / -1' }}>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Descripción</label>
                                  <input type="text" value={editFormPedido.descripcion} onChange={ev => setEditFormPedido({ ...editFormPedido, descripcion: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }} />
                                </div>
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Cantidad</label>
                                  <input type="number" value={editFormPedido.cantidad} onChange={ev => setEditFormPedido({ ...editFormPedido, cantidad: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }} />
                                </div>
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Fecha compra</label>
                                  <input type="date" value={editFormPedido.fecha_compra} onChange={ev => setEditFormPedido({ ...editFormPedido, fecha_compra: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }} />
                                </div>
                                {/* Cotizador */}
                                {(() => {
                                  const iSt = { width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }
                                  const lSt = { color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }
                                  const usd = parseFloat(editFormPedido.precio_usd) || 0
                                  const tcVal = parseFloat(editFormPedido.tipo_cambio) || 0
                                  const impPct = parseFloat(editFormPedido.impuesto_pct) || 0
                                  const imp = impPct / 100
                                  const costoCalc = usd > 0 && tcVal > 0 ? usd * (1 + imp) * tcVal : parseFloat(editFormPedido.costo_mxn) || 0
                                  const venta = parseFloat(editFormPedido.precio_venta) || 0
                                  const util = venta - costoCalc
                                  const margen = venta > 0 ? (util / venta) * 100 : 0
                                  const setTax = (tipo) => {
                                    const pct = tipo === 'arizona' ? 8.6 : tipo === 'california' ? 7.75 : parseFloat(ecTaxDenogPct) || 0
                                    const nc = usd > 0 && tcVal > 0 ? usd * (1 + pct/100) * tcVal : parseFloat(editFormPedido.costo_mxn) || 0
                                    setEcTaxTipo(tipo)
                                    setEditFormPedido(prev => ({ ...prev, impuesto_pct: pct, costo_mxn: nc, utilidad: venta - nc }))
                                  }
                                  const handleUsd = (val) => {
                                    const nu = parseFloat(val) || 0
                                    const nc = nu > 0 && tcVal > 0 ? nu * (1 + imp) * tcVal : 0
                                    setEditFormPedido(prev => ({ ...prev, precio_usd: val, costo_mxn: nc || prev.costo_mxn, utilidad: venta - (nc || parseFloat(prev.costo_mxn) || 0) }))
                                  }
                                  const handleTc = (val) => {
                                    const nt = parseFloat(val) || 0
                                    const nc = usd > 0 && nt > 0 ? usd * (1 + imp) * nt : 0
                                    setEditFormPedido(prev => ({ ...prev, tipo_cambio: val, costo_mxn: nc || prev.costo_mxn, utilidad: venta - (nc || parseFloat(prev.costo_mxn) || 0) }))
                                  }
                                  const handleDenogPct = (val) => {
                                    setEcTaxDenogPct(val)
                                    const pct = parseFloat(val) || 0
                                    const nc = usd > 0 && tcVal > 0 ? usd * (1 + pct/100) * tcVal : parseFloat(editFormPedido.costo_mxn) || 0
                                    setEditFormPedido(prev => ({ ...prev, impuesto_pct: pct, costo_mxn: nc, utilidad: venta - nc }))
                                  }
                                  const handleVenta = (val) => {
                                    setEditFormPedido(prev => ({ ...prev, precio_venta: val, utilidad: (parseFloat(val) || 0) - costoCalc }))
                                  }
                                  return (
                                    <div style={{ gridColumn: '1 / -1', background: 'rgba(99,102,241,0.06)', border: '1px solid rgba(99,102,241,0.18)', borderRadius: 10, padding: 12 }}>
                                      <div style={{ color: '#818cf8', fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 10 }}>💱 Cotizador</div>
                                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 8 }}>
                                        <div><label style={lSt}>Precio USD</label><input type="number" step="0.01" value={editFormPedido.precio_usd} onChange={ev => handleUsd(ev.target.value)} style={iSt} placeholder="Ej. 14.99" /></div>
                                        <div><label style={lSt}>Tipo de cambio</label><input type="number" step="0.01" value={editFormPedido.tipo_cambio} onChange={ev => handleTc(ev.target.value)} style={iSt} /></div>
                                      </div>
                                      <div style={{ marginBottom: 8 }}>
                                        <label style={lSt}>Impuesto</label>
                                        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                                          {[['arizona','Arizona 8.6%'],['california','California 7.75%'],['denog','Tax Denog']].map(([k,lbl]) => (
                                            <button key={k} type="button" onClick={() => setTax(k)}
                                              style={{ padding: '3px 8px', borderRadius: 6, fontSize: 10, fontWeight: 600, cursor: 'pointer', border: `1px solid ${ecTaxTipo === k ? 'rgba(99,102,241,0.5)' : 'rgba(255,255,255,0.1)'}`, background: ecTaxTipo === k ? 'rgba(99,102,241,0.2)' : 'rgba(255,255,255,0.04)', color: ecTaxTipo === k ? '#818cf8' : 'rgba(255,255,255,0.45)' }}>
                                              {lbl}
                                            </button>
                                          ))}
                                        </div>
                                        {ecTaxTipo === 'denog' && <input type="number" step="0.01" value={ecTaxDenogPct} onChange={ev => handleDenogPct(ev.target.value)} placeholder="%" style={{ ...iSt, marginTop: 5, width: '50%' }} />}
                                      </div>
                                      {usd > 0 && tcVal > 0 && (
                                        <div style={{ background: 'rgba(0,0,0,0.2)', borderRadius: 7, padding: '7px 9px', fontSize: 10, display: 'grid', gap: 2, marginBottom: 8 }}>
                                          <div style={{ display: 'flex', justifyContent: 'space-between', color: 'rgba(255,255,255,0.4)' }}><span>Precio USD</span><span style={{ fontFamily: 'monospace' }}>${usd.toFixed(2)}</span></div>
                                          <div style={{ display: 'flex', justifyContent: 'space-between', color: 'rgba(255,255,255,0.4)' }}><span>+ Impuesto ({impPct.toFixed(2)}%)</span><span style={{ fontFamily: 'monospace' }}>+${(usd * imp).toFixed(2)}</span></div>
                                          <div style={{ display: 'flex', justifyContent: 'space-between', color: 'rgba(255,255,255,0.4)' }}><span>× TC {tcVal}</span></div>
                                          <div style={{ display: 'flex', justifyContent: 'space-between', color: 'white', fontWeight: 700, borderTop: '1px solid rgba(255,255,255,0.08)', paddingTop: 4, marginTop: 2 }}><span>= Costo MXN</span><span style={{ fontFamily: 'monospace', color: '#f59e0b' }}>${costoCalc.toFixed(2)}</span></div>
                                        </div>
                                      )}
                                      <div>
                                        <label style={lSt}>Precio de venta MXN</label>
                                        <input type="number" step="0.01" value={editFormPedido.precio_venta} onChange={ev => handleVenta(ev.target.value)} style={iSt} />
                                        {editFormPedido.precio_venta && costoCalc > 0 && (
                                          <div style={{ display: 'flex', gap: 10, marginTop: 4, fontSize: 10 }}>
                                            <span style={{ color: util >= 0 ? '#4ade80' : '#f87171' }}>Utilidad: ${util.toFixed(2)}</span>
                                            <span style={{ color: margen >= 20 ? '#4ade80' : margen >= 0 ? '#f59e0b' : '#f87171' }}>Margen: {margen.toFixed(1)}%</span>
                                          </div>
                                        )}
                                      </div>
                                    </div>
                                  )
                                })()}
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Estado</label>
                                  <select value={editFormPedido.estado} onChange={ev => setEditFormPedido({ ...editFormPedido, estado: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }}>
                                    {['Pendiente', 'En camino', 'En tienda', 'Entregado', 'Cancelado'].map(s => <option key={s} value={s}>{s}</option>)}
                                  </select>
                                </div>
                                <div>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Vendedor</label>
                                  <select value={editFormPedido.vendedor_id} onChange={ev => setEditFormPedido({ ...editFormPedido, vendedor_id: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }}>
                                    <option value="">— ninguno —</option>
                                    {vendedoresOpts.map(v => <option key={v.id} value={v.id}>{v.nombre}</option>)}
                                  </select>
                                </div>
                                <div style={{ gridColumn: '1 / -1' }}>
                                  <label style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10, display: 'block', marginBottom: 3 }}>Notas</label>
                                  <input type="text" value={editFormPedido.notas} onChange={ev => setEditFormPedido({ ...editFormPedido, notas: ev.target.value })}
                                    style={{ width: '100%', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 7, padding: '6px 9px', color: 'white', fontSize: 11, outline: 'none', boxSizing: 'border-box' }} placeholder="Opcional" />
                                </div>
                              </div>
                              {pedidoMsg && <div style={{ color: '#f87171', fontSize: 11, marginBottom: 8 }}>{pedidoMsg}</div>}
                              <div style={{ display: 'flex', gap: 8 }}>
                                <button onClick={guardarPedidoEdit} disabled={guardandoPedido}
                                  style={{ background: '#6366f1', border: 'none', borderRadius: 7, padding: '6px 14px', color: 'white', fontSize: 11, fontWeight: 600, cursor: 'pointer', opacity: guardandoPedido ? 0.6 : 1 }}>
                                  {guardandoPedido ? 'Guardando...' : '✓ Guardar'}
                                </button>
                                <button onClick={() => setEditandoPedido(null)}
                                  style={{ background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 7, padding: '6px 14px', color: 'rgba(255,255,255,0.4)', fontSize: 11, cursor: 'pointer' }}>
                                  Cancelar
                                </button>
                              </div>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                    {(() => {
                      const pagosAnt = g.pagos.filter(pg => !pg.tipo?.toLowerCase().includes('liquidaci'))
                      if (pagosAnt.length === 0 || g.totalEntregadosOriginal !== undefined) return null
                      const emojiMetodo = (m) => m === 'Efectivo' ? '💵' : m === 'Transferencia' ? '📱' : m === 'Terminal' ? '💳' : m
                      const totalAnt = pagosAnt.reduce((s, pg) => s + pg.monto, 0)
                      const fechaAnt = pagosAnt[0]?.creado_en
                      const porMetodo = pagosAnt.reduce((acc, pg) => {
                        if (!pg.metodo) return acc
                        acc[pg.metodo] = (acc[pg.metodo] || 0) + pg.monto
                        return acc
                      }, {})
                      return (
                        <div style={{ borderLeft: '4px solid #16a34a', background: '#dcfce7', borderRadius: '0 6px 6px 0', padding: '8px 12px', marginBottom: 6, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div>
                            <div style={{ color: '#166534', fontSize: 13, fontWeight: 700, marginBottom: 3 }}>
                              ✓ Anticipos aplicados{fechaAnt ? ` · ${fmtFecha(fechaAnt.split('T')[0])}` : ''}
                            </div>
                            <div style={{ color: '#15803d', fontSize: 10 }}>
                              {Object.entries(porMetodo).map(([m, monto]) => `${emojiMetodo(m)} ${m}: ${fmt(monto)}`).join(' · ')}
                            </div>
                          </div>
                          <span style={{ color: '#166534', fontSize: 13, fontWeight: 800, fontFamily: 'monospace' }}>-{fmt(totalAnt)}</span>
                        </div>
                      )
                    })()}
                    {(() => {
                      const pagosLiq = g.pagos.filter(pg => pg.tipo?.toLowerCase().includes('liquidaci'))
                      if (pagosLiq.length === 0 || g.totalEntregadosOriginal !== undefined) return null
                      const emojiMetodo = (m) => m === 'Efectivo' ? '💵' : m === 'Transferencia' ? '📱' : m === 'Terminal' ? '💳' : m
                      const porMetodo = pagosLiq.reduce((acc, pg) => {
                        if (!pg.metodo) return acc
                        acc[pg.metodo] = (acc[pg.metodo] || 0) + pg.monto
                        return acc
                      }, {})
                      const totalLiq = pagosLiq.reduce((s, pg) => s + pg.monto, 0)
                      const fechaLiq = pagosLiq[0]?.creado_en
                      return (
                        <div style={{ borderLeft: '4px solid #1d4ed8', background: '#dbeafe', borderRadius: '0 6px 6px 0', padding: '8px 12px', marginBottom: 6, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div>
                            <div style={{ color: '#1d4ed8', fontSize: 13, fontWeight: 700, marginBottom: 3 }}>
                              ✓ Liquidado{fechaLiq ? ` · ${fmtFecha(fechaLiq.split('T')[0])}` : ''}
                            </div>
                            <div style={{ color: '#1e40af', fontSize: 10 }}>
                              {Object.entries(porMetodo).map(([m, monto]) => `${emojiMetodo(m)} ${m}: ${fmt(monto)}`).join(' · ')}
                            </div>
                          </div>
                          <span style={{ color: '#1d4ed8', fontSize: 13, fontWeight: 800, fontFamily: 'monospace' }}>{fmt(totalLiq)}</span>
                        </div>
                      )
                    })()}
                  </div>
                )
              })}

              {(() => {
                const saldo = clienteActual.grupos.reduce((s, g) => {
                  const totalEntregados = g.totalEntregadosOriginal ?? g.pedidos.filter(p => p.estado === 'Entregado').reduce((ss, p) => ss + (p.precio_venta || 0), 0)
                  const totalPendientes = g.pedidos.filter(p => p.estado !== 'Entregado').reduce((ss, p) => ss + (p.precio_venta || 0), 0)
                  const pagadoGrupo = g.pagos.reduce((ss, p) => ss + (p.monto || 0), 0)
                  const sobrante = Math.max(0, pagadoGrupo - totalEntregados)
                  return s + Math.max(0, totalPendientes - sobrante)
                }, 0)
                return (
                  <div style={{ marginTop: 16, background: 'rgba(239,68,68,0.07)', border: '1px solid rgba(239,68,68,0.14)', borderRadius: 10, padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ color: '#f87171', fontSize: 13, fontWeight: 600 }}>Total a pagar</span>
                    <span style={{ color: '#f87171', fontSize: 22, fontWeight: 800 }}>{fmt(saldo)}</span>
                  </div>
                )
              })()}
            </div>

            {/* Imagen del estado de cuenta */}
            {imagenURL && (
              <div style={{ marginBottom: 14, borderRadius: 12, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.08)' }}>
                <img src={imagenURL} alt="Estado de cuenta" style={{ width: '100%', display: 'block' }} />
              </div>
            )}
            {!imagenURL && (
              <div style={{ marginBottom: 14, borderRadius: 12, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.06)', height: 80, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'rgba(255,255,255,0.2)', fontSize: 13 }}>
                Generando imagen...
              </div>
            )}

            {/* Botones principales */}
            <div style={{ display: 'flex', gap: 10, marginBottom: 10 }}>
              <button onClick={() => copiarAlPortapapeles(clienteActual)} disabled={!imagenURL}
                style={{ flex: 2, padding: '14px', borderRadius: 12, background: copiado ? 'rgba(74,222,128,0.15)' : 'rgba(99,102,241,0.2)', border: `1px solid ${copiado ? 'rgba(74,222,128,0.35)' : 'rgba(99,102,241,0.4)'}`, color: copiado ? '#4ade80' : '#818cf8', fontSize: 15, fontWeight: 700, cursor: imagenURL ? 'pointer' : 'default', opacity: imagenURL ? 1 : 0.4, transition: 'all 0.25s', letterSpacing: 0.3 }}>
                {copiado ? '✅ ¡Copiada!' : '📋 Copiar imagen'}
              </button>
              {clienteActual.cliente.telefono ? (
                <a href={`https://wa.me/${((tel) => { const n = tel.replace(/\D/g, ''); if (n.length === 12 && n.startsWith('52')) return n; if (n.length === 10) return '52' + n; if (n.length === 11 && n.startsWith('1')) return '52' + n.slice(1); if (n.length === 11 && !n.startsWith('52')) return '52' + n.slice(1); if (n.length === 13 && n.startsWith('521')) return '52' + n.slice(3); return n; })(clienteActual.cliente.telefono)}`} target="_blank" rel="noreferrer"
                  style={{ flex: 1, padding: '14px', borderRadius: 12, background: 'rgba(37,211,102,0.12)', border: '1px solid rgba(37,211,102,0.3)', color: '#4ade80', fontSize: 15, fontWeight: 700, cursor: 'pointer', textAlign: 'center', textDecoration: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
                  📱 WhatsApp
                </a>
              ) : (
                <div style={{ flex: 1, padding: '14px', borderRadius: 12, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.05)', color: 'rgba(255,255,255,0.18)', fontSize: 13, textAlign: 'center', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  Sin tel.
                </div>
              )}
            </div>
            <button onClick={() => setIndice(i => Math.min(datos.length - 1, i + 1))} disabled={indice >= datos.length - 1}
              style={{ width: '100%', padding: '12px', borderRadius: 12, background: indice < datos.length - 1 ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.02)', border: `1px solid ${indice < datos.length - 1 ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)'}`, color: indice < datos.length - 1 ? 'rgba(255,255,255,0.6)' : 'rgba(255,255,255,0.15)', fontSize: 14, fontWeight: 600, cursor: indice < datos.length - 1 ? 'pointer' : 'default' }}>
              Siguiente cliente → ({indice + 1} / {datos.length})
            </button>
          </>
        )}

        {!cargando && datos.length === 0 && entregaId && modo === 'entrega' && (
          <div style={{ textAlign: 'center', color: 'rgba(255,255,255,0.25)', fontSize: 13, padding: 40 }}>
            No hay clientes con pedidos pendientes en esta entrega
          </div>
        )}
      </div>
    </div>
  )
}
